      if (state.after===0) { state.pinnedMessage=data.pinnedMessage||null; renderPinned(); }
      for (const message of data.messages) { state.after = Math.max(state.after, Number(message.id) || 0); host.append(renderMessage(message, message.senderId === state.user.id)); }
