  $('#locationButton').onclick=()=>{const host=$('#modalHost');host.innerHTML=`<div class="overlay" id="overlay"><section class="modal glass"><div class="modal-head"><h2>Поделиться геопозицией</h2><button id="closeLocation" class="icon" aria-label="Закрыть">×</button></div><p class="info" style="text-align:left;padding:0 0 12px">Metto запросит местоположение только после твоего нажатия. Точка будет отправлена в этот чат ссылкой на карту.</p><button id="sendLocation" class="primary">⌖ Отправить мою геопозицию</button></section></div>`;const close=()=>closeModal();$('#closeLocation').onclick=close;$('#overlay').onclick=e=>{if(e.target.id==='overlay')close()};$('#sendLocation').onclick=()=>{const button=$('#sendLocation');if(!navigator.geolocation){toast('Браузер не поддерживает геопозицию');return}button.disabled=true;button.textContent='Определяем…';navigator.geolocation.getCurrentPosition(async position=>{try{await sendMessage(`[[metto-location]]${position.coords.latitude},${position.coords.longitude}`);close()}finally{button.disabled=false}},error=>{button.disabled=false;button.textContent='⌖ Отправить мою геопозицию';toast(error.code===1?'Разреши геопозицию в браузере, чтобы отправить точку.':'Не удалось определить геопозицию.')},{enableHighAccuracy:true,timeout:12000,maximumAge:30000})};};

  function showSpecial(title, content, back = showWelcome) { state.current = ''; state.view = title.toLowerCase(); $('#welcome').classList.add('hidden'); $('#chatHead').classList.add('hidden'); $('#peerBanner').classList.add('hidden'); $('#messages').classList.add('hidden'); $('#composer').classList.add('hidden'); $('#chatInfo').classList.add('hidden'); $('#specialView').classList.remove('hidden'); $('#specialTitle').textContent = title; $('#specialContent').replaceChildren(); if (typeof content === 'function') content($('#specialContent')); $('#specialBack').onclick = back; $('#favoriteAdd').classList.toggle('hidden', title !== 'Избранное'); $('#pane').classList.add('mobile-open'); $('#sidebar').classList.add('mobile-hidden');$('#app').classList.add('mobile-chat-active'); }
